+
+      .hero {
+        padding: 32px;
+        margin-bottom: 24px;
+        border: 1px solid rgba(219, 228, 240, 0.9);
+        border-radius: calc(var(--radius) + 4px);
+        background: linear-gradient(180deg, var(--surface), rgba(255, 255, 255, 0.78));
+        backdrop-filter: blur(14px);
+        box-shadow: var(--shadow);
+      }
+
+      .eyebrow {
+        display: inline-flex;
+        align-items: center;
+        gap: 8px;
+        padding: 8px 12px;
+        margin: 0 0 16px;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: var(--accent);
+        font-size: 0.875rem;
+        font-weight: 700;
+        letter-spacing: 0.02em;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2rem, 5vw, 3.5rem);
+        line-height: 1.05;
+        letter-spacing: -0.04em;
+      }
+
+      .subtitle {
+        max-width: 60ch;
+        margin: 14px 0 0;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.6;
+      }
+
+      .faq {
+        display: grid;
+        gap: 14px;
+      }
+
+      .example {
+        overflow: hidden;
+        border: 1px solid var(--border);
+        border-radius: var(--radius);
+        background: var(--surface-strong);
+        box-shadow: 0 10px 30px rgba(19, 32, 51, 0.05);
+      }
+
+      .question {
+        width: 100%;
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        gap: 18px;
+        padding: 22px 24px;
+        border: 0;
+        background: transparent;
+        color: inherit;
+        font: inherit;
+        text-align: left;
+        cursor: pointer;
+      }
+
+      .question:hover {
+        background: rgba(79, 124, 255, 0.05);
+      }
+
+      .question:focus-visible {
+        outline: 3px solid rgba(79, 124, 255, 0.35);
+        outline-offset: -3px;
+      }
+
+      .question-text {
+        margin: 0;
+        font-size: 1.08rem;
+        font-weight: 700;
+        line-height: 1.4;
+      }
+
+      .icon {
+        flex: none;
+        width: 36px;
+        height: 36px;
+        display: grid;
+        place-items: center;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: var(--accent);
+        font-size: 1.25rem;
+        font-weight: 700;
+        transition: transform 180ms ease, background-color 180ms ease;
+      }
+
+      .question[aria-expanded="true"] .icon {
+        transform: rotate(45deg);
+        background: #dde7ff;
+      }
+
+      .details {
+        padding: 0 24px 22px;
+        color: var(--muted);
+        line-height: 1.7;
+      }
+
+      .details p {
+        margin: 0;
+      }
+
+      .details[hidden] {
+        display: none;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100% - 20px, 920px);
+          padding: 24px 0 40px;
+        }
+
+        .hero,
+        .question,
+        .details {
+          padding-left: 18px;
+          padding-right: 18px;
+        }
+
+        .hero {
+          padding-top: 24px;
+          padding-bottom: 24px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main class="page">
+      <section class="hero" aria-labelledby="faq-title">
+        <p class="eyebrow">Cat FAQ</p>
+        <h1 id="faq-title">Everything you wanted to know about cats</h1>
+        <p class="subtitle">
+          A compact, friendly guide to the quirks, habits, and care basics that make cats such
+          fascinating companions.
+        </p>
+      </section>
+
+      <section class="faq" aria-label="Frequently asked questions">
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="cat-q1">
+            <span class="question-text">Why do cats purr?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="cat-q1" hidden>
+            <p>
+              Cats often purr when they feel relaxed and safe, but they may also purr while
+              recovering, self-soothing, or asking for attention. Think of it as a versatile
+              communication tool, not just a sign of happiness.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="cat-q2">
+            <span class="question-text">How much sleep do cats need?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="cat-q2" hidden>
+            <p>
+              Most cats sleep between 12 and 16 hours a day, and some kittens or senior cats may
+              sleep even more. Their energy tends to come in short bursts, usually when they are
+              ready to play, hunt, or zoom around the house.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="cat-q3">
+            <span class="question-text">Why do cats knead blankets?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="cat-q3" hidden>
+            <p>
+              Kneading is a comforting behavior linked to kittenhood, when cats pressed against
+              their mothers while nursing. Adult cats often keep doing it when they are calm,
+              content, or settling into a soft spot.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="cat-q4">
+            <span class="question-text">How can I keep my cat entertained?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="cat-q4" hidden>
+            <p>
+              Rotate toys, add vertical spaces like shelves or cat trees, and schedule short play
+              sessions with wand toys or puzzle feeders. Variety matters more than quantity, so
+              even a few interactive minutes can make a big difference.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="cat-q5">
+            <span class="question-text">Do cats recognize their names?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="cat-q5" hidden>
+            <p>
+              Yes, many cats learn to recognize their names, especially when the sound leads to
+              food, play, or attention. They may still choose to ignore you, which is very on
+              brand for cats.
+            </p>
+          </div>
+        </div>
+      </section>
+    </main>
+
+    <script>
+      document.querySelectorAll(".example").forEach((example) => {
+        const button = example.querySelector(".question");
+        const details = example.querySelector(".details");
+
+        button.addEventListener("click", () => {
+          const isExpanded = button.getAttribute("aria-expanded") === "true";
+          button.setAttribute("aria-expanded", String(!isExpanded));
+          details.hidden = isExpanded;
+        });
+      });
+    </script>
+  </body>
+</html>
*** End Patch
